// Recuerda hasta qué created_at ya avisamos (persistente entre ejecuciones).
const sd = $getWorkflowStaticData('global');
const lastAt = sd.lastAt || new Date(Date.now() - 5 * 60 * 1000).toISOString();
return [{ json: { lastAt } }];

// Solicitudes nuevas + teléfono del documento (configurable en /admin → Datos).
const nuevas = $('Solicitudes nuevas').all().map(i => i.json).filter(r => r && r.id && r.name);
if (nuevas.length === 0) return [];
const docRows = $('Leer documento CRM').first().json;
const rows = Array.isArray(docRows) ? docRows : (docRows && docRows.body) || [];
const doc = Array.isArray(rows) ? (rows[0] && rows[0].data) : undefined;
const telefono = (doc && doc.settings && doc.settings.notifyPhone) || $env.MALONIC_NICO_PHONE;
if (!telefono) return [];
// Avanzar la marca al created_at más reciente avisado (evita duplicados).
const sd = $getWorkflowStaticData('global');
const maxAt = nuevas.map(r => r.created_at).sort().at(-1);
if (maxAt) sd.lastAt = maxAt;
return nuevas.map(r => {
  const partes = [
    `🎙 Nueva solicitud en malonicrecords`,
    `${r.name} · ${r.email}`,
    r.service ? `Servicio: ${r.service}` : null,
    r.project ? `Proyecto: ${r.project}` : null,
    r.message ? `“${String(r.message).slice(0, 180)}”` : null,
    `Revisar: https://malonic-website.vercel.app/admin`,
  ].filter(Boolean);
  return { json: { mensaje: partes.join('\n'), telefono } };
});
